task_info = "Outputs the anomaly probability (0-1) of the source node:"

reddit_info = "Reddit is public dataset consists of one month of posts made by users on subreddits. It selects the 1,000 most active subreddits as items and the 10,000 most active users. This results in 672,447 interactions. It converts the text of each post into a feature vector representing their LIWC categories."
wikipedia_info = "Wikipedia is public dataset is one month of edits made by edits on Wikipedia pages. It selected the 1,000 most edited pages as items and editors who made at least 5 edits as users (a total of 8,227 users). This generates 157,474 interactions. It converts the edit text into a LIWC-feature vector."
mooc_info = "Mooc is public dataset consists of actions, e.g., viewing a video, submitting an answer, etc., done by students on a MOOC online course. This dataset consists of 7,047 users interacting with 98 items (videos, answers, etc.) resulting in over 411,749 interactions."
